sysevent_script_action.script:
var url = gs.getProperty('slack_webhook_url');
if (!url) gs.warn('Agent Chat Notification: webhook URL property is empty');

var inc = current.incident.getRefRecord();
var assigned_agent = current.getDisplayValue('assigned_agent');
var assignment_type = current.getDisplayValue('assignment_type');
var assigned_group = current.getDisplayValue('assigned_group');
var reason = current.getDisplayValue('reason');
var timestamp = current.getDisplayValue('timestamp');

var message = inc.getDisplayValue('number') + " - " + inc.getDisplayValue('short_description') + " is assigned to " + assigned_agent + " belongs to " + assigned_group + " group with a assignment type = " + assignment_type + " Because " + reason + " [" + timestamp + "]";

try {
    var r = new sn_ws.RESTMessageV2();
    r.setEndpoint(url);
    r.setHttpTimeout(10000);
    r.setHttpMethod("post");
    r.setRequestHeader("Content-Type", "Application/json");
    r.setRequestBody(JSON.stringify({
        "text": message
    }));
    var res = r.execute();
    var code = res.getStatusCode();
    if (code != 200) gs.warn('Agent Chat Notification failed: HTTP ' + code + ' ' + res.getBody());
} catch (e) {
    gs.warn('Agent Chat Notification error: ' + e);
}
